Definition sn_sr : list expr :=
  Eval cbv in (map (fun i => match i with
                          | 0 => ELit 0 | 2 => EVar 0 | 11 => ELit 2147483647
                          | _ => EVar (2 + i) end)%nat (seq 0 32)).

