Definition sn_cells : list (Z * nat * Z) :=
  [(0x11d2f0, 8%nat, 0x10e09c);   (* [comment removed for export] *)
   (0x11d1d0, 8%nat, 0x10d67c);   (* [comment removed for export] *)
   (0x129478, 8%nat, 0x7fff8000); (* [comment removed for export] *)
